#!/usr/bin/env python3
import argparse,json,html
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('native',type=Path);p.add_argument('common',type=Path);p.add_argument('output',type=Path);a=p.parse_args();native=json.loads(a.native.read_text());common=json.loads(a.common.read_text());groups={}
for c in native['cases']:
 for v in c['variants']:groups.setdefault(v['id'],[]).append((v['warmMedianMs'],None))
for c in common['cases']:
 r=c['result'];groups.setdefault(r['algorithm'],[]).append((r['warmMedianMs'],(r['metrics']['massRatio']-1)*100))
labels={'original':'Оригинал','lazy':'Точная оптимизация шума','one-octave':'Одна октава','alternative-finite-volume-exchange':'Новый перенос пигмента','alternative-correlated-paper-deposition':'Бумажное осаждение','alternative-stable-fluids':'Stable Fluids','alternative-artistic-front':'Быстрый фронт','wgsl-d2q9-bgk':'LBM'}
rows=''
for key,values in groups.items():
 times=[v[0] for v in values];mass=[v[1] for v in values if v[1] is not None];rows+='<tr><td>'+html.escape(labels[key])+'</td><td>'+format(min(times),'.1f')+'–'+format(max(times),'.1f')+' мс</td><td>'+((format(min(mass),'+.2f')+'…'+format(max(mass),'+.2f')+'%') if mass else '—')+'</td></tr>'
text='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Как сравнивали акварель</title><style>*{box-sizing:border-box}body{background:#f2f1ed;color:#252723;font:16px/1.6 system-ui;margin:0}main{max-width:900px;margin:auto;padding:24px}a{color:#3e664c}h1{line-height:1.2}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:10px;border-bottom:1px solid #ccc}.table{overflow:auto}li{margin:10px 0}@media(max-width:500px){main{padding:14px}}</style><main><a href="./">← Карточки мазков</a><h1>Как проводили сравнение</h1><p>11 примеров восстановлены из настоящих записанных мазков галереи — по одному с листов 1–10 и 12. Сохранены нажим, форма кисти, последовательность действий, вода и пигмент. Геометрия каждого примера вместе с размером кисти равномерно вписана в 700 пикселей и помещена в центр листа 1024×1024. Это воспроизведение условий, а не копия пикселей исторической комнаты. Ещё две сцены повторяют геометрию волны и двух цветов из проверки октав; точки ввода зафиксированы заново.</p><p>Все сцены явно переключены на текущий Mini front8-detail-flow-v4. Сверялось фактически выбранное состояние материала, а не только настройка стенда. Пробные расчёты старого режима из исторических записей исключены.</p><h2>Оригинал и оптимизации</h2><p>39 запусков в свежем движке, по 5 расчётов каждого варианта. В карточке — медиана четырёх повторов после первого. Во всех парах совпали исходные поля краски, воды, подложки и бумаги, а также хеш реально проигранных действий. Точная оптимизация сохранила полные поля и PNG побайтно. Одна октава допускает изменение рисунка: она была быстрее на 12 из 13 примеров, на одном — медленнее. Порядок вариантов фиксирован, поэтому это наблюдение этого прогона, не универсальная гарантия ускорения.</p><p>Замер включает подготовку цели из неподвижного исходника, растекание, сушку и финальный композит до зависимого чтения одного пикселя. Полное чтение, SHA и PNG идут после таймера. Это не изолированное время GPU и не полный путь от пера до следующего видимого кадра.</p><h2>Другие алгоритмы</h2><p>Пять моделей получили одинаковые захваченные поля каждого из 13 примеров: 65 случаев, по три расчёта, все повторы совпали побайтно на Samsung. При показе оптической плотности компенсируется записанный глобальный масштаб захвата. Полный композитор Mini эти модели не повторяют. Поэтому в карточках у них указано время расчёта без процента ускорения относительно оригинала.</p><p>Технические проверки не означают принятия художественного качества. На расширенном наборе отклонения суммы alpha оказались больше, чем на первых тестах. Alpha используется лишь как прокси количества пигмента; значения доступны в подробностях каждого варианта и в таблице. Почти сухой край новой модели также остаётся открытым вопросом.</p><div class="table"><table><tr><th>Вариант</th><th>Медианы на 13 примерах</th><th>Изменение суммы alpha к входу</th></tr>ROWS</table></div><h2>Что здесь не проверялось</h2><p>Совпадение между разными устройствами, свободное рисование новыми моделями, комнаты, undo/redo, A2, тайлы и полный отклик интерфейса Grafetto. Изображения и аппаратные расчёты получены на Samsung Tab S7+ / Adreno 650; headless браузер использовался только для проверки страницы.</p><p><a href="comparison.json">Все параметры, повторы и контрольные хеши карточек</a> · <a href="night-report.html">Первый ночной отчёт с четырьмя направлениями поиска</a></p></main></html>'''
a.output.write_text(text.replace('ROWS',rows))
